 result={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'fixed_collection_and_frozen_feature_cache_complete_no_training','splits':split_summary,'transitions':transitions,'unique_window_label_distribution':distribution,'root_outcomes':roots,'controller_status_counts':dict(collections.Counter(r['primitive_status']for r in rows)),'failure_reasons':dict(collections.Counter(r['primitive_reason']for r in rows if r['primitive_reason'])),'posthold_losses':[r['pair_id']for r in rows if r['wait_held_loss']],'posthold_label_changes':[r['pair_id']for r in rows if r['wait_label_changes']],'posthold_max_object_displacement_mm':max(r['wait_max_object_mm']for r in rows),'posthold_max_TCP_displacement_mm':max(r['posthold']['TCP_max_displacement_mm']for r in rows),'posthold_max_drawer_drift_mm':max(r['posthold']['drawer_max_drift_mm']for r in rows),'registry_missing':cache['identity_missing'],'registry_wrong_present':cache['identity_mismatch_present'],'no_D_observations_or_inference':True,'new_training_updates':0,'candidate_reader_forwards':0,'fixed_candidate_unchanged':True,'local_only':True};save(E/'results/summary.json',result);save(E/'results/pair_details.json',rows)
