 save(E/'figures/index.json',visual_index)
 hdr='<!doctype html><html lang="zh"><meta charset="utf-8"><title>2.1秒双端宏转移数据核验</title><style>body{font:16px system-ui;line-height:1.65;color:#203647;max-width:1240px;margin:35px auto;padding:0 24px}table{border-collapse:collapse;width:100%;font-size:13px;margin:20px 0}th,td{border:1px solid #ccd7df;padding:6px;text-align:left}th{background:#e9f0f4}img{max-width:100%;height:auto}code{font-size:13px}details{margin:14px 0;padding:10px;background:#f4f7fa}a{color:#126192}.bad{color:#a23c2a}.muted{color:#627581}h1{line-height:1.3}</style>'
 body='<h1>严格2.1秒双端配对采集已完成</h1><p>固定24个全新A/B训练根、6个全新C开发根，三色平衡，120次宏调用均保留。此交付证明数据接口、因果时间和文件可用性；尚未训练或运行候选读出模型，不能据此声称新世界模型或规划性能改善。</p>'
 body+='<p>训练与开发各自的根完全隔离。每个C颜色有一根调参、一根校准。仅使用历史根布局元数据排除近重复；未采集新D，也未读取D图像进行训练或选型。原控制器、候选权重、标签和预处理均保持哈希一致。</p>'
 ss=split_summary;body+=table(['划分','新根','宏配对 / 独立边界窗','双端7项全有效','部分有效','至少1项有效变化','全7项有效且不变','技能本体成功 / 失败 / 拒绝','等待后目标成立'],[[s,ss[s]['roots'],f"{ss[s]['pairs']} / {ss[s]['unique_windows']}",ss[s]['both_all7_valid_pairs'],ss[s]['partially_valid_pairs'],ss[s]['valid_changed_pairs'],ss[s]['all7_valid_unchanged_pairs'],f"{ss[s]['primitive_successes']} / {ss[s]['primitive_failed']} / {ss[s]['primitive_refused']}",ss[s]['endpoint_requested_goal_sustained']]for s in ['train','dev']])
 body+='<p>“可用配对”分两层：所有120对都有完整双端公共输入与声明动作；监督按原有效掩码逐事实使用，7项全有效配对单独计数。GT边界不确定项保留为无效，不将其改为假、不删除整个失败样本，也不只监督目标物体。</p>'
 if all(r['primitive_status']=='success'for r in rows):body+='<p>本次固定顺序下没有自然产生技能失败或拒绝；这些类别的数量是0，不能声称已覆盖失败转移。没有为制造负样本追加宏调用。</p>'
 if sum(ss[s]['all7_valid_unchanged_pairs']for s in ss)==0:body+='<p>本批没有7项状态全部不变的宏配对；所有正常完成的宏至少改变一项任务事实。大量不变事实来自同一配对中的无关物体，但不等同于整状态不变的负样本。后续方法不得混淆这两种覆盖。</p>'
 body+='<h2>已定位的输入注册风险</h2><p>原公共像素颜色注册在遮挡情况下可能把棕色桌面误登记为红块。第一处直接证据：真实红块在四帧双相机中完全不可见，桌面区域均值R/G超过原1.7阈值，满足红色规则。所有错误实际输入保留；没有用真值ID替换、屏蔽相关监督、修改候选或挑掉配对。标签正确与视觉槽位正确分别审计，数据采集通过不等于状态接口验收通过。</p><img src="figures/registry_first_wrong_full.png">'
 body+=table(['划分','涉及可见错配的配对','涉及缺失槽位的配对','双端三实体注册都正确','注册正确且双端7项GT全有效'],[[s]+[registry['splits'][s][k]for k in ['pairs_with_present_wrong_slot','pairs_with_missing_slot','all_entity_registry_correct_both_endpoints','all_entity_registry_correct_and_all7_GT_valid_both_endpoints']]for s in ['train','dev']])
 body+='<p>表中类别可能重叠。缺失槽位沿用零特征，属于原接口允许的缺失情形；可见错配则把其他区域特征放进目标槽位。计数用于说明输入质量，不是授权过滤这些样本。<a href="results/registry_diagnostic_full.json">逐窗像素证据与受影响配对</a>。</p>'
 body+='<h2>时间与动作的固定约定</h2><p>第一次调用前，现有安全保持执行96个控制步（宏区间之外）。每次调用执行冻结技能本体，随后保持96步（宏区间之内），保持当时公开夹爪指令。下一调用从前一次等待终点开始。每个边界取[t−63,t−42,t−21,t]四帧，真实跨度2.1秒，间隔0.7秒。240Hz物理步长来自保存的原生配置；运行时验证30Hz控制频率，并逐步实计每控制8个物理步。这里的秒数是仿真时间，墙钟采集耗时另记。3.2秒等待提供充分过去历史；没有重复帧填充、未来观测或状态注入。</p><p>闭抽屉起始顺序：open→lift→place→close；开抽屉起始顺序：lift→place→close→open。单技能原预算900步、原内部有限重试不变，拒绝也照实记录，并执行约定的96步等待。未来训练和测试必须沿用这一定义；实际持续时间、成功标志和私有阶段不能作为预测动作输入。</p>'
 body+='<h2>每种事实发生了什么</h2><img src="figures/transitions.png"><p>横轴为宏配对数量，纵轴为7个任务事实；左图A/B训练96对，右图C开发24对。蓝色=双端有效且不变，绿色=假→真，橙色=真→假，灰色=至少一端物理标签无效。同一宏可改变多个事实，因此各行不能相加作为宏数。不变项是对无关物体保持状态的监督。</p>'
 for s in ['train','dev']:body+='<h3>'+s+'</h3>'+table(['事实','0→0','0→1','1→0','1→1','任一端无效'],[[r[k]for k in ['predicate','0to0','0to1','1to0','1to1','invalid_either_endpoint']]for r in transitions[s]])
 body+='<p>held沿用双侧手指接触且没有外部承重接触的物理定义；in沿用held覆盖后的主drawer ownership定义，并不表示任意几何包含；open沿用抽屉位置阈值及原5mm有效边界。open=false可包含中间开度，并不等同抽屉已关闭；关抽屉完成另按原控制器小于0.02m的条件记录。全类别私有状态仅用于取证，模型监督只有held/in/open这7项，不要求回归8类位置。</p>'
 body+='<h2>等待的物理影响与失败</h2><img src="figures/wait_motion.png"><p>横轴为清单配对顺序（固定试采根先执行），纵轴为等待期间三物体中最大的离起点位移，单位mm；小位移区域线性、较大区域对数显示。蓝点A/B，橙点C。位移是检查等待是否改变状态的证据，不能直接当作掉落；掉落另按逐帧held丢失记录。</p>'
 body+=f'<p>等待期间发生held丢失的宏：{len(result["posthold_losses"])}；有效标签改变的宏：{len(result["posthold_label_changes"])}。最大物体位移{result["posthold_max_object_displacement_mm"]:.4f}mm，最大TCP位移{result["posthold_max_TCP_displacement_mm"]:.4f}mm，最大抽屉漂移{result["posthold_max_drawer_drift_mm"]:.4f}mm。原技能失败原因计数：<code>{html.escape(json.dumps(result["failure_reasons"],ensure_ascii=False))}</code>。失败后未增加根、宏调用或调整控制器。</p>'
 fails=[r for r in roots if r['first_consequential_failure']];body+=table(['根','第一处有影响的失败','对应配对','本根7项全有效配对'],[[r['root_id'],html.escape(r['first_consequential_failure']['reason']),r['first_consequential_failure']['pair_id'],r['both_all7_valid_pairs']]for r in fails])if fails else'<p>所有根的四个请求目标均在等待后成立。</p>'
 wait=read(E/'results/wait_audit.json');body+=f'<p>逐帧补充审计覆盖30次初始保持和120次宏后保持，共14400个真实控制步。held真→假事件{wait["held_loss_events"]}次，有效事实变化{wait["valid_fact_change_events"]}次，有效性跳变{wait["validity_change_events"]}次；30个held终点在对应64帧中持续held。边界2.1秒窗口仍有微动：最大物体位移{wait["boundary_max_object_motion_mm"]:.4f}mm、TCP位移{wait["boundary_max_TCP_motion_mm"]:.4f}mm。<a href="results/wait_audit.json">逐帧等待审计</a>。</p>'
